# Independent check: UCS graph search (goal test on removal, frontier replacement, no re-expansion)
E={'S':{'A':1,'B':4,'G':12},'A':{'C':2,'D':5},'B':{'D':1},'C':{'G':8},'D':{'G':3},'G':{}}
frontier={'S':(0,('S',))}; closed=set(); order=[]
while frontier:
    n=min(frontier,key=lambda k:(frontier[k][0],k)); g,path=frontier.pop(n); order.append(n)
    if n=='G': break
    closed.add(n)
    for m,c in E[n].items():
        if m not in closed and (m not in frontier or g+c<frontier[m][0]): frontier[m]=(g+c,path+(m,))
opts={'A':(list('SABG'),12),'B':(list('SACG'),11),'C':(list('SACBDG'),8),'D':(list('SACBDG'),12)}
print(order,g,path,[k for k,v in opts.items() if v==(order,g)])
assert [k for k,v in opts.items() if v==(order,g)]==['C']
