# Independent check: (1) active-trail enumeration for d-separation, (2) numeric test with random CPTs
import itertools, numpy as np
edges=[('O','S'),('N','S'),('S','U'),('N','T')]
nodes='ONSUT'
ch={n:[b for a,b in edges if a==n] for n in nodes}; pa={n:[a for a,b in edges if b==n] for n in nodes}
nbr={n:set(ch[n])|set(pa[n]) for n in nodes}
def desc(n):
    out=set(); st=[n]
    while st:
        for c in ch[st.pop()]:
            if c not in out: out.add(c); st.append(c)
    return out
def active(path,Z):   # path = list of nodes; every interior node must be non-blocking
    for i in range(1,len(path)-1):
        a,b,c=path[i-1],path[i],path[i+1]
        collider=(a in pa[b]) and (c in pa[b])
        if collider:
            if b not in Z and not (desc(b)&Z): return False
        elif b in Z: return False
    return True
def dsep(x,y,Z):
    def walk(p):
        if p[-1]==y: yield p; return
        for m in nbr[p[-1]]:
            if m not in p: yield from walk(p+[m])
    return not any(active(p,Z) for p in walk([x]))
res={'A':dsep('O','N',{'U'}),'B':dsep('O','T',{'S'}),'C':dsep('O','T',set()),'D':dsep('U','T',set())}
print(res); assert [k for k,v in res.items() if v]==['C']
# numeric: random CPTs -> exact joint; test independence
rng=np.random.default_rng(3)
def joint():
    pO,pN=rng.random(2); pS=rng.random((2,2)); pU=rng.random(2); pT=rng.random(2); J=np.zeros((2,)*5)
    for o,n,s,u,t in itertools.product((0,1),repeat=5):
        J[o,n,s,u,t]=(pO if o else 1-pO)*(pN if n else 1-pN)*(pS[o,n] if s else 1-pS[o,n])*(pU[s] if u else 1-pU[s])*(pT[n] if t else 1-pT[n])
    return J
J=joint(); ax={v:i for i,v in enumerate(nodes)}
def indep(x,y,z):
    keep=[x,y]+list(z); other=tuple(i for v,i in ax.items() if v not in keep)
    M=J.sum(axis=other); srt=sorted(keep,key=lambda v:ax[v]); M=np.transpose(M,[srt.index(v) for v in keep])
    for zz in itertools.product((0,1),repeat=len(z)):
        sub=M[(slice(None),slice(None))+zz]; sub=sub/sub.sum()
        if not np.allclose(sub,np.outer(sub.sum(1),sub.sum(0))): return False
    return True
num={'A':indep('O','N','U'),'B':indep('O','T','S'),'C':indep('O','T',''),'D':indep('U','T','')}
print(num); assert num==res

# Independent check: h*(n) by Floyd-Warshall on the undirected graph; largest integer k with h(n) <= h*(n) for all n
import itertools
E=[('S','A',3),('S','B',4),('A','C',2),('B','C',1),('A','G',11),('C','D',6),('C','E',2),('D','G',2),('E','G',5)]
V='SABCDEG'; INF=10**9
d={(u,v):(0 if u==v else INF) for u in V for v in V}
for u,v,w in E: d[u,v]=d[v,u]=min(d[u,v],w)
for k,i,j in itertools.product(V,V,V): d[i,j]=min(d[i,j],d[i,k]+d[k,j])
hstar={n:d[n,'G'] for n in V}
base={'S':10,'A':8,'B':6,'D':2,'E':4,'G':0}
adm=lambda k:all(h<=hstar[n] for n,h in {**base,'C':k}.items())
best=max(k for k in range(-5,40) if adm(k))
print(hstar,best)
assert best==7 and adm(7) and not adm(8)

# Independent check: exhaustive model comparison (all structures with 1-3 employees) against the intended reading
from itertools import product
for n in (1,2,3):
    D=range(n); bad=set('ABCD')
    for Mv in product((0,1),repeat=n):
        for Rv in product((0,1),repeat=n*n):
            M=lambda x:Mv[x]; R=lambda x,y:Rv[x*n+y]
            target=all(M(x) or any(M(y) and R(x,y) for y in D) for x in D)
            f={'A':all(M(x) or any(M(y) and R(x,y) for y in D) for x in D),
               'B':all(any((not M(x)) and M(y) and R(x,y) for y in D) for x in D),
               'C':not any((not M(x)) and all((not M(y)) or (not R(x,y)) for y in D) for x in D),
               'D':all(M(x) or any((not M(y)) or R(x,y) for y in D) for x in D)}
            bad-={k for k,v in f.items() if v!=target}
    print(n,sorted(bad))
    # 'bad' now holds options that matched the target in every model
assert sorted(bad)==['A','C']
